function CanonicalHeight(c, x, N):
    val <- x
    for i = 0 to N-1:
        val <- val^2 + c
    return log|val| / 2^N

Complexity: O(N * M(2^N)) where M(B) = cost of B-bit multiplication

function BenfordScan(c_min, c_max, P, K):
    primes <- Sieve(P)
    for c = c_min to c_max:
        counts <- zeros(9)
        for p in primes:
            val <- p
            for n = 1 to K:
                val <- val^2 + c
                counts[LeadDigit(val)] += 1
        D_KL[c] <- KL_Divergence(counts, Benford)
    return D_KL

Complexity: O((c_max-c_min) * pi(P) * K * M(2^K))
